create table if not exists public.budget_data(user_id uuid primary key references auth.users(id) on delete cascade,data jsonb not null,updated_at timestamptz not null default now());alter table public.budget_data enable row level security;create policy "Users can read own budget" on public.budget_data for select to authenticated using(auth.uid()=user_id);create policy "Users can insert own budget" on public.budget_data for insert to authenticated with check(auth.uid()=user_id);create policy "Users can update own budget" on public.budget_data for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "Users can delete own budget" on public.budget_data for delete to authenticated using(auth.uid()=user_id);grant select,insert,update,delete on public.budget_data to authenticated;